CREATE POLICY tenant_isolation ON customer_risk_rating USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_customer_risk_rating_touch BEFORE UPDATE ON customer_risk_rating FOR EACH ROW EXECUTE FUNCTION touch_row();

-- risk_graph_entity: Node in the risk graph (customer, account, device, IP, phone, beneficiary, ...)
CREATE TABLE risk_graph_entity (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  entity_type                  varchar(40) NOT NULL CHECK (entity_type IN ('CUSTOMER', 'ACCOUNT', 'CARD', 'DEVICE', 'IP_ADDRESS', 'PHONE', 'EMAIL', 'ADDRESS', 'BENEFICIARY', 'MERCHANT')),
  entity_ref                   varchar(128) NOT NULL,
  customer_id                  uuid,
  risk_score                   integer NOT NULL DEFAULT 0,
  community_id                 varchar(64),
  is_mule_suspect              boolean NOT NULL DEFAULT false,
  last_seen_at                 timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_risk_graph_entity_1 UNIQUE (tenant_id, entity_type, entity_ref)
);
COMMENT ON TABLE risk_graph_entity IS 'Node in the risk graph (customer, account, device, IP, phone, beneficiary, ...)';
COMMENT ON COLUMN risk_graph_entity.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN risk_graph_entity.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN risk_graph_entity.created_at IS 'Creation time';
COMMENT ON COLUMN risk_graph_entity.created_by IS 'Principal that created the row';
COMMENT ON COLUMN risk_graph_entity.updated_at IS 'Last update time';
COMMENT ON COLUMN risk_graph_entity.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN risk_graph_entity.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN risk_graph_entity.entity_type IS 'Node type';
COMMENT ON COLUMN risk_graph_entity.entity_ref IS 'Business id or hashed value of the node';
COMMENT ON COLUMN risk_graph_entity.customer_id IS 'Customer, when the node belongs to one';
COMMENT ON COLUMN risk_graph_entity.risk_score IS 'Propagated risk score 0-1000';
COMMENT ON COLUMN risk_graph_entity.community_id IS 'Detected community / cluster';
COMMENT ON COLUMN risk_graph_entity.is_mule_suspect IS 'Flagged by mule detection';
COMMENT ON COLUMN risk_graph_entity.last_seen_at IS 'Last activity';
COMMENT ON COLUMN risk_graph_entity.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_entity.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_entity.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_entity.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_entity.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_risk_graph_entity_tenant ON risk_graph_entity (tenant_id, created_at);
CREATE INDEX ix_risk_graph_entity_customer_id ON risk_graph_entity (customer_id);
CREATE INDEX ix_risk_graph_entity_community_id ON risk_graph_entity (community_id);
ALTER TABLE risk_graph_entity ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON risk_graph_entity USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_risk_graph_entity_touch BEFORE UPDATE ON risk_graph_entity FOR EACH ROW EXECUTE FUNCTION touch_row();

-- risk_graph_link: Edge between two graph entities (shared device, transfer, shared address, ...)
CREATE TABLE risk_graph_link (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  from_entity_id               uuid NOT NULL REFERENCES risk_graph_entity(id),
  to_entity_id                 uuid NOT NULL REFERENCES risk_graph_entity(id),
  link_type                    varchar(40) NOT NULL,
  weight                       numeric(18,10) NOT NULL DEFAULT 1,
  transaction_count            integer NOT NULL DEFAULT 0,
  total_amount                 numeric(28,8) NOT NULL DEFAULT 0,
  first_seen_at                timestamptz NOT NULL,
  last_seen_at                 timestamptz NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_risk_graph_link_1 UNIQUE (from_entity_id, to_entity_id, link_type)
);
COMMENT ON TABLE risk_graph_link IS 'Edge between two graph entities (shared device, transfer, shared address, ...)';
COMMENT ON COLUMN risk_graph_link.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN risk_graph_link.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN risk_graph_link.created_at IS 'Creation time';
COMMENT ON COLUMN risk_graph_link.created_by IS 'Principal that created the row';
COMMENT ON COLUMN risk_graph_link.updated_at IS 'Last update time';
COMMENT ON COLUMN risk_graph_link.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN risk_graph_link.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN risk_graph_link.from_entity_id IS 'Source node';
COMMENT ON COLUMN risk_graph_link.to_entity_id IS 'Target node';
COMMENT ON COLUMN risk_graph_link.link_type IS 'SHARED_DEVICE, TRANSFER, SHARED_ADDRESS, SHARED_PHONE, SHARED_IP, OWNS';
COMMENT ON COLUMN risk_graph_link.weight IS 'Edge weight';
COMMENT ON COLUMN risk_graph_link.transaction_count IS 'Transfers along the edge';
COMMENT ON COLUMN risk_graph_link.total_amount IS 'Amount transferred along the edge';
COMMENT ON COLUMN risk_graph_link.first_seen_at IS 'First observed';
COMMENT ON COLUMN risk_graph_link.last_seen_at IS 'Last observed';
COMMENT ON COLUMN risk_graph_link.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_link.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_link.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_link.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN risk_graph_link.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_risk_graph_link_tenant ON risk_graph_link (tenant_id, created_at);
CREATE INDEX ix_risk_graph_link_from_entity_id ON risk_graph_link (from_entity_id);
CREATE INDEX ix_risk_graph_link_to_entity_id ON risk_graph_link (to_entity_id);
ALTER TABLE risk_graph_link ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON risk_graph_link USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_risk_graph_link_touch BEFORE UPDATE ON risk_graph_link FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA tm TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA tm TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA tm GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
